for r in random_password.team_db local_sensitive_file.team_env; do i=0; for t in checkout search web; do printf 'moved {
  from = %s[%d]
  to   = %s["%s"]
}
' $r $i $r $t; i=$((i+1)); done; done > moved.tf

sed -i '/^  type = map(object({ tier = string, owner = string }))$/a\  validation {
    condition     = alltrue([for name, t in var.teams : contains(["gold", "silver"], t.tier)])
    error_message = "Every team tier must be gold or silver."
  }
  validation {
    condition     = alltrue([for name, t in var.teams : can(regex("^[^@ ]+@[^@ ]+\\.[a-z]+$", t.owner))])
    error_message = "Every team owner must be an e-mail address."
  }' main.tf
